// gear.json is generated by scripts/build-gear-data.mjs from the scraped wiki tables.
import type { GearGroup, GearItem } from '../types';
import gearData from './content/gear.json';

const GROUPS = gearData as Record<GearGroup, GearItem[]>;

export const GEAR_BY_GROUP: Record<GearGroup, GearItem[]> = {
  Hands: GROUPS.Hands ?? [],
  Shield: GROUPS.Shield ?? [],
  Legs: GROUPS.Legs ?? [],
  Accessory: GROUPS.Accessory ?? [],
};

/** Names are unique across all groups; `build-gear-data.mjs` fails on a collision. */
export const GEAR: Record<string, GearItem> = Object.fromEntries(
  Object.values(GEAR_BY_GROUP).flat().map(item => [item.name, item]),
);

/** Hands pieces and shields are separate wiki pages but share slot 3. */
export const SLOT3_GEAR: GearItem[] = [...GEAR_BY_GROUP.Hands, ...GEAR_BY_GROUP.Shield]
  .sort((a, b) => a.name.localeCompare(b.name));

/** Shields additionally grant the Guard skill. */
export function isShield(name: string | null | undefined): boolean {
  return Boolean(name) && GEAR_BY_GROUP.Shield.some(item => item.name === name);
}

export function gearByName(name: string | null | undefined): GearItem | undefined {
  if (!name) return undefined;
  return GEAR[name];
}
